import{_ as t,o as e,a as l,b as r}from"./app.C41L12d5.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"GetMDLConfig","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMDLConfig"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMDLConfig.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMDLConfig.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787294517000}'),s={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMDLConfig.md"};function n(i,a,d,b,o,p){return e(),l("div",null,[...a[0]||(a[0]=[r(`<div><article class="markdown-body"><h1>GetMDLConfig</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>用于配置MDL模板的参数，获取自定义MDL模板。MDL模板的介绍请参考<a href="MatmulConfig.html#template-features">表模板特性</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__aicore__ constexpr MatmulConfig GetMDLConfig(const bool intrinsicsLimit = false, const bool batchLoop = false, const uint32_t doMTE2Preload = 0, const bool isVecND2NZ = false, bool isPerTensor = false, bool hasAntiQuantOffset = false, const bool enUnitFlag = false, const bool isMsgReuse = true, const bool enableUBReuse = true, const bool enableL1CacheUB = false, const bool enableMixDualMaster = false, const bool enableKdimReorderLoad = false)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>本接口的所有参数用于设置<a href="MatmulConfig.html#matmulconfig-params">MatmulConfig结构体</a>中的参数，其中互相对应的参数的功能作用相同。</p><p><strong>表1</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>intrinsicsLimit</td><td>输入</td><td>用于设置参数intrinsicsCheck。<br><br>当左矩阵或右矩阵在单核上内轴（即尾轴）大于等于65535（元素个数）时，是否开启循环执行数据从Global Memory到L1 Buffer的搬入。例如，左矩阵A[M, K]，单核上的内轴数据singleCoreK大于65535，配置该参数为true后，API内部通过循环执行数据的搬入。参数取值如下：<br>false：当左矩阵或右矩阵在单核上内轴大于等于65535时，不开启循环执行数据的搬入（默认值）。<br>true：当左矩阵或右矩阵在单核上内轴大于等于65535时，开启循环执行数据的搬入。<span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</span></td></tr><tr><td>batchLoop</td><td>输入</td><td>用于设置参数isNBatch。<br><br>是否多Batch输入多Batch输出。仅对BatchMatmul有效，开启多Batch后，仅支持Norm模板，且需调用<a href="IterateNBatch.html">IterateNBatch</a>实现多Batch输入多Batch输出。参数取值如下：<br>false：不开启多Batch（默认值）。<br>true：开启多Batch。</td></tr><tr><td>doMTE2Preload</td><td>输入</td><td>用于设置参数doMTE2Preload。<br><br>在MTE2流水间隙较大，且M/N数值较大时可通过该参数开启对应M/N方向的预加载功能，开启后能减小MTE2间隙，提升性能。预加载功能仅在MDL模板有效（不支持SpecialMDL模板）。参数取值如下：<br>0：不开启（默认值）。1：开启M方向preload。2：开启N方向preload。<br><br>注意：开启M/N方向的预加载功能时需保证K全载且M/N方向开启DoubleBuffer；其中，M方向的K全载条件为：singleCoreK/baseK &lt;= stepKa；N方向的K全载条件为：singleCoreK/baseK &lt;= stepKb。</td></tr><tr><td>isVecND2NZ</td><td>输入</td><td>用于设置参数enVecND2NZ。<br><br>开启通过vector指令进行ND2NZ。开启时需要设置<a href="SetLocalWorkspace.html">SetLocalWorkspace</a>。参数取值如下：<br>false：不开启通过vector指令进行ND2NZ（默认值）。<br>true：开启通过vector指令进行ND2NZ。<span data-filter="310p"><br><br>针对Atlas 推理系列产品AI Core，在Unified Buffer（UB）空间足够的条件下（UB空间大于2倍TCubeTiling的<a href="../Matmul_Tiling/TCubeTiling_struct.html#p1620315053211">transLength</a>参数），建议优先开启，搬运性能更好。</span><span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</span></td></tr><tr><td>isPerTensor</td><td>输入</td><td>用于设置参数isPerTensor。<br><br>A矩阵half类型输入且B矩阵int8_t类型输入场景，开启B矩阵量化时是否为per tensor。<br>true：per tensor量化。<br>false：per channel量化。<span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</span></td></tr><tr><td>hasAntiQuantOffset</td><td>输入</td><td>用于设置参数hasAntiQuantOffset。<br><br>A矩阵half类型输入且B矩阵int8_t类型输入场景，开启B矩阵量化时是否使用offset系数。<span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</span></td></tr><tr><td>enUnitFlag</td><td>输入</td><td>用于设置参数enUnitFlag。<br><br>开启UnitFlag功能，使计算与搬运流水并行，提高性能。Norm, IBShare下默认开启，MDL下默认不开启。参数取值如下：<br>false：不开启UnitFlag功能。<br>true：开启UnitFlag功能。<span data-filter="950"><br><br>注意：对于Ascend 950PR/Ascend 950DT的MxMatmul场景，仅在NORM/MDL模板、A和scaleA不转置、 B和scaleB转置、C为ND格式，输出到GM场景下，开启UnitFlag功能有性能收益。</span></td></tr><tr><td>isMsgReuse</td><td>输入</td><td>用于设置参数enableReuse。<br><br><a href="SetSelfDefineData.html">SetSelfDefineData</a>函数设置的回调函数中的dataPtr是否直接传递计算数据。若未调用SetSelfDefineData设置dataPtr，该参数仅支持默认值true。参数取值如下：<br>true：直接传递计算数据，仅限单个值。<br>false：传递GM上存储的数据地址信息。<span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持该参数。</span></td></tr><tr><td>enableUBReuse</td><td>输入</td><td>用于设置参数enableUBReuse。<br><br>是否开启UB复用。在UB空间足够的条件下（UB空间大于4倍TCubeTiling的<a href="../Matmul_Tiling/TCubeTiling_struct.html#p1620315053211">transLength</a>参数），设置开启UB复用后，UB空间分为互不重叠的两份，分别存储Matmul计算相邻前后两轮迭代的数据，后一轮迭代数据的搬入将不必等待前一轮迭代的UB空间释放，从而优化流水。参数取值如下：<br>true：开启UB复用。<br>false：不开启UB复用。<span data-filter="950"><br><br>包括MxMatmul场景，Ascend 950PR/Ascend 950DT不支持该参数。</span><span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品不支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br><br>Kirin X90不支持此参数。</span></td></tr><tr><td>enableL1CacheUB</td><td>输入</td><td>用于设置参数enableL1CacheUB 。<br><br>是否开启L1 Buffer缓存UB计算块。建议在MTE3和MTE2流水串行较多的场景使用。参数取值如下：<br>true：开启L1 Buffer缓存UB计算块。<br>false：不开启L1 Buffer缓存UB计算块。<br><br>若要开启L1 Buffer缓存UB计算块，必须在Tiling实现中调用<a href="../Matmul_Tiling/SetMatmulConfigParams.html">SetMatmulConfigParams</a>接口将参数enableL1CacheUBIn设置为true。<span data-filter="950"><br><br>包括MxMatmul场景，Ascend 950PR/Ascend 950DT不支持该参数。</span><span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品不支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br><br>Kirin X90不支持此参数。</span></td></tr><tr><td>enableMixDualMaster</td><td>输入</td><td>用于设置参数enableMixDualMaster。<br><br>是否开启MixDualMaster（双主模式）。区别于MIX模式（包含矩阵计算和矢量计算）通过消息机制驱动AIC运行，双主模式为AIC和AIV独立运行代码，不依赖消息驱动，用于提升性能。该参数默认值为false，仅能在以下场景设置为true：<br>核函数（Kernel）的类型为MIX，同时AIC核数 : AIV核数为1:1。<br>核函数（Kernel）的类型为MIX，同时AIC核数 : AIV核数为1:2，且A矩阵和B矩阵同时开启<a href="Matmul_usage.html#table1188045714378">IBSHARE</a>参数。<br><br>注意，开启MixDualMaster场景，需要满足：<br>同一算子中所有Matmul对象的该参数取值必须保持一致。<br>A/B/Bias矩阵只支持从GM搬入。<br>获取矩阵计算结果只支持调用<a href="IterateAll.html">IterateAll</a>接口输出到GlobalTensor或者LocalTensor，即计算结果放置于Global Memory或者Local Memory的地址，不能调用<a href="GetTensorC.html">GetTensorC</a>等接口获取结果。<span data-filter="950"><br><br>除MxMatmul场景外，Ascend 950PR/Ascend 950DT支持该参数。</span><span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core不支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br><br>Kirin X90不支持此参数。</span></td></tr><tr><td>enableKdimReorderLoad</td><td>输入</td><td>用于设置参数enableKdimReorderLoad。<br><br>是否开启K轴错峰加载数据。基于相同Tiling参数，执行Matmul计算时，如果多核的左矩阵或者右矩阵相同，且存储于Global Memory，多个核一般会同时访问相同地址以加载矩阵数据，引发同地址访问冲突，影响性能。开启K轴错峰加载数据后，多核执行Matmul时，将尽量在相同时间访问矩阵的不同Global Memory地址，减少地址访问冲突概率，提升性能。该参数功能只支持MDL模板，建议K轴较大且左矩阵和右矩阵均非全载场景开启该功能。参数取值如下。<br>false：默认值，关闭K轴错峰加载数据的功能。<br>true：开启K轴错峰加载数据的功能。<span data-filter="950"><br><br>除MxMatmul场景外，Ascend 950PR/Ascend 950DT支持该参数。</span><span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core不支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br><br>Kirin X90支持此参数。</span></td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p><a href="MatmulConfig.html#matmulconfig-params">MatmulConfig结构体</a>。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 配置MDL模板的参数，获取自定义MDL模板
constexpr MatmulConfig MM_CFG = GetMDLConfig(
    /* intrinsicsLimit      */ false,
    /* batchLoop            */ false,
    /* doMTE2Preload        */ 0,
    /* isVecND2NZ           */ false,
    /* isPerTensor          */ false,
    /* hasAntiQuantOffset   */ false,
    /* enUnitFlag           */ false,
    /* isMsgReuse           */ true,
    /* enableUBReuse        */ true,
    /* enableL1CacheUB      */ false,
    /* enableMixDualMaster  */ false,
    /* enableKdimReorderLoad*/ false);
// 常规Matmul计算，最后输出使用自定义MDL模板的计算结果
AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);
mm.SetTensorA(gm_a);
mm.SetTensorB(gm_b);
if (tiling.isBias) {
    mm.SetBias(gmBias);
}
mm.IterateAll(gm_c);
mm.End();
</code></pre></div></article></div>`,1)])])}const A=t(s,[["render",n]]);export{f as __pageData,A as default};
